args.content:
import { getNotificationPreference, toggleNotifications } from "./actions";

export default async function Home() {
  const enabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{enabled ? "on" : "off"}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn {enabled ? "off" : "on"} notifications
        </button>
      </form>
    </main>
  );
}

